contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit);

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint bankBefore = c.bank().balance;
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        c.play{value: deposit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint bankAfter = c.bank().balance;
        uint cBalanceAfter = address(c).balance;

        uint bankPaid = bankAfter - bankBefore;
        uint callerPaid = cBalanceBefore + deposit - cBalanceAfter;

        assert((reverted && potAfter == potBefore) || (!reverted && bankPaid + callerPaid <= potBefore + deposit));
    }

    receive() external payable {}
}

