pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint bankBefore = c.bank().balance;
        uint cBalanceBefore = address(c).balance;
        bool reverted;
        try c.play{value: deposit}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint bankAfter = c.bank().balance;
        uint cBalanceAfter = address(c).balance;
        uint bankPaid = bankAfter - bankBefore;
        uint callerPaid = cBalanceBefore + deposit - cBalanceAfter;
        assertTrue((reverted && potAfter == potBefore) || (!reverted && bankPaid + callerPaid <= potBefore + deposit));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
